props.leftCode:
setInterval(async () => {
  // Llega 3 segundos tarde y te banean la IP
  const book = await fetch('/api/v3/orderbook');
  if (book.spread > 0.015) takeOrder();
}, 3000);

props.rightCode:
ws.on('message', (frame) => {
  const offer = decodeBinaryFrame(frame);
  if (offer.spread >= MIN_SPREAD && scoreUser(offer) > 95) {
    executeSignedOrder(offer); // 18ms total
  }
});
